              <div class="grid grid-cols-2 sm:grid-cols-4 gap-2 text-xs font-extrabold">
                <div class="p-2.5 rounded-xl bg-white dark:bg-slate-800 border border-amber-200 text-center">1️⃣ تدقيق متقاطع</div>
                <div class="p-2.5 rounded-xl bg-white dark:bg-slate-800 border border-amber-200 text-center">2️⃣ طلب المصدر</div>
                <div class="p-2.5 rounded-xl bg-white dark:bg-slate-800 border border-amber-200 text-center">3️⃣ تفكير نقدي</div>
                <div class="p-2.5 rounded-xl bg-white dark:bg-slate-800 border border-amber-200 text-center">4️⃣ تحقق بشري</div>
              </div>
